/** Display name of a set, or `""` for an unknown id. */
export function outfitSetName(setId: number): string {
  return OUTFIT_SETS[setId]?.名前 ?? "";
}

/**
 * Reverse lookup by name — the `[[…]]` → id step of `@EX_COSTUME`
 * (`GETMETH_INT(C_ID, "キャラデータ", …, @"%TYPE%衣装")` then
 * `@衣装セット_ID` / `FINDELEMENT`).
 */
export function outfitSetIdByName(name: string): number | undefined {
  for (const [idStr, set] of Object.entries(OUTFIT_SETS)) {
    if (set.名前 === name) return Number(idStr);
  }
  return undefined;
}
